  ('gravatar', 'Gravatar', ARRAY['email'], 1, 86400, 'gravatar-public-profile', NULL, NULL, NULL, NULL, 'Consulta publica por hash do e-mail; o provedor nao publica cota', 'nao_publicado', false, 'Responde 404 quando o e-mail nao tem avatar: e resposta legitima, nao falha.', '{"sem_chave":"A fonte nao rodou porque a credencial do operador nao esta configurada. Nao e falha real: o restante do relatorio continua valendo e o relatorio nao fica parcial.","sem_token":"A fonte nao rodou por falta de token de uso unico valido (ausente, expirado, reutilizado ou vinculado a outro alvo). Falha de sessao, nao do provedor.","erro_rede":"Falha de DNS, conexao ou TLS ao falar com o provedor. Em geral e bloqueio do IP de saida (reputacao) ou provedor fora do ar; a fonte repassa a mensagem crua.","timeout":"O prazo da consulta estourou antes da resposta. Causas Frequentes: provedor lento, cota do orcamento de subrequests do scan ou fila do provedor.","http":"404 significa que o e-mail nao tem gravatar (resposta legitima); 429/403 indicam bloqueio por IP.","formato":"A resposta chegou, mas fora do formato esperado (JSON invalido, HTML de erro ou campo ausente). Em geral o provedor mudou o contrato.","erro":"Falha nao classificada pela taxonomia. O detalhe fica no log privado do Worker; o relatorio publica apenas a mensagem bounded."}'::jsonb),
  ('pgp', 'PGP', ARRAY['email'], 1, 604800, 'keys-openpgp', NULL, NULL, NULL, NULL, 'Consulta publica ao keys.openpgp.org; sem cota publicada', 'nao_publicado', false, '200 com lista vazia significa que o e-mail nao tem chave publica: nao e falha.', '{"sem_chave":"A fonte nao rodou porque a credencial do operador nao esta configurada. Nao e falha real: o restante do relatorio continua valendo e o relatorio nao fica parcial.","sem_token":"A fonte nao rodou por falta de token de uso unico valido (ausente, expirado, reutilizado ou vinculado a outro alvo). Falha de sessao, nao do provedor.","erro_rede":"Falha de DNS, conexao ou TLS ao falar com o provedor. Em geral e bloqueio do IP de saida (reputacao) ou provedor fora do ar; a fonte repassa a mensagem crua.","timeout":"O prazo da consulta estourou antes da resposta. Causas Frequentes: provedor lento, cota do orcamento de subrequests do scan ou fila do provedor.","http":"200 sem chaves e resposta legitima; 429 indica limite por IP do provedor.","formato":"A resposta chegou, mas fora do formato esperado (JSON invalido, HTML de erro ou campo ausente). Em geral o provedor mudou o contrato.","erro":"Falha nao classificada pela taxonomia. O detalhe fica no log privado do Worker; o relatorio publica apenas a mensagem bounded."}'::jsonb),
  ('gitlab', 'GitLab', ARRAY['email'], 1, 21600, 'gitlab-graphql-search', NULL, NULL, NULL, NULL, 'Busca GraphQL publica; cota do GitLab por IP nao documentada aqui', 'nao_publicado', false, 'A API GraphQL exige POST: a fonte usa a rota de busca por e-mail.', '{"sem_chave":"A fonte nao rodou porque a credencial do operador nao esta configurada. Nao e falha real: o restante do relatorio continua valendo e o relatorio nao fica parcial.","sem_token":"A fonte nao rodou por falta de token de uso unico valido (ausente, expirado, reutilizado ou vinculado a outro alvo). Falha de sessao, nao do provedor.","erro_rede":"Falha de DNS, conexao ou TLS ao falar com o provedor. Em geral e bloqueio do IP de saida (reputacao) ou provedor fora do ar; a fonte repassa a mensagem crua.","timeout":"O prazo da consulta estourou antes da resposta. Causas Frequentes: provedor lento, cota do orcamento de subrequests do scan ou fila do provedor.","http":"O provedor respondeu com status HTTP inesperado. 429 e limite de cota por IP; 401/403 e credencial recusada ou bloqueada; 5xx e falha do provedor.","formato":"A resposta GraphQL volta em envelope (data/users) ou com errors: a fonte le o envelope e acusa formato invalido quando ele falta.","erro":"Falha nao classificada pela taxonomia. O detalhe fica no log privado do Worker; o relatorio publica apenas a mensagem bounded."}'::jsonb),
  ('npm', 'npm', ARRAY['email'], 1, 21600, 'npm-registry', NULL, NULL, NULL, NULL, 'Registro publico; sem cota publicada', 'nao_publicado', false, 'Registro de pacotes: a fonte procura pacotes com o e-mail no campo maintainers.', '{"sem_chave":"A fonte nao rodou porque a credencial do operador nao esta configurada. Nao e falha real: o restante do relatorio continua valendo e o relatorio nao fica parcial.","sem_token":"A fonte nao rodou por falta de token de uso unico valido (ausente, expirado, reutilizado ou vinculado a outro alvo). Falha de sessao, nao do provedor.","erro_rede":"Falha de DNS, conexao ou TLS ao falar com o provedor. Em geral e bloqueio do IP de saida (reputacao) ou provedor fora do ar; a fonte repassa a mensagem crua.","timeout":"O prazo da consulta estourou antes da resposta. Causas Frequentes: provedor lento, cota do orcamento de subrequests do scan ou fila do provedor.","http":"O provedor respondeu com status HTTP inesperado. 429 e limite de cota por IP; 401/403 e credencial recusada ou bloqueada; 5xx e falha do provedor.","formato":"A resposta chegou, mas fora do formato esperado (JSON invalido, HTML de erro ou campo ausente). Em geral o provedor mudou o contrato.","erro":"Falha nao classificada pela taxonomia. O detalhe fica no log privado do Worker; o relatorio publica apenas a mensagem bounded."}'::jsonb),
